mapper.select:
SELECT * FROM "user" 
WHERE oauth_provider = #{oauthProvider} 
AND oauth_id = #{oauthId} 
AND status != 'deleted'

SELECT u.id, u.username, u.email, u.status, up.display_name AS displayName, up.avatar_url AS avatarUrl, u.last_login_at AS lastLoginAt, u.created_at AS createdAt FROM "user" u LEFT JOIN user_profiles up ON u.id = up.user_id WHERE u.status != 'deleted'
AND u.username LIKE CONCAT('%', #{params.username}, '%')
AND up.display_name LIKE CONCAT('%', #{params.displayName}, '%')
AND u.email = #{params.email}
AND u.account_type = #{params.accountType}
AND u.status = #{params.status}
AND u.created_at >= #{params.pageable.startTime}
AND u.created_at <= #{params.pageable.endTime}
AND DATE(u.created_at) = #{params.pageable.date}
ORDER BY
u.created_at u.last_login_at u.username u.email up.display_name u.created_at
DESC ASC
u.created_at DESC

SELECT COUNT(DISTINCT u.id)
FROM "user" u
LEFT JOIN user_profiles up ON u.id = up.user_id
WHERE u.status != 'deleted'

    AND u.username LIKE CONCAT('%', #{params.username}, '%')


    AND up.display_name LIKE CONCAT('%', #{params.displayName}, '%')


    AND u.email = #{params.email}


    AND u.account_type = #{params.accountType}


    AND u.status = #{params.status}


    AND u.created_at >= #{params.pageable.startTime}


    AND u.created_at <= #{params.pageable.endTime}


    AND DATE(u.created_at) = #{params.pageable.date}
